DROP DATABASE IF EXISTS Rybobaza;
CREATE DATABASE IF NOT EXISTS Rybobaza
CHARACTER SET UTF8MB4;

USE Rybobaza;

CREATE TABLE Rybiki (
   id_ryby INT AUTO_INCREMENT PRIMARY KEY,
   nazwa_ryby VARCHAR(100) NOT NULL,
   typ_ryby VARCHAR(50) NOT NULL,
   dlugosc_srednia_cm FLOAT CHECK (dlugosc_srednia_cm >= 0),
   waga_srednia_g FLOAT CHECK (waga_srednia_g >= 0),
   opis TEXT,
   czy_tropikalna BOOL DEFAULT FALSE,
   ostatnia_aktualizacja TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

RENAME TABLE Rybiki TO Ryby;
TRUNCATE TABLE Ryby;

CREATE TABLE Jedzenie (
   id_jedzenia INT AUTO_INCREMENT PRIMARY KEY,
   nazwa VARCHAR(50) NOT NULL UNIQUE,
   opis TEXT
);

CREATE TABLE Zagrozenia (
   id_zagrozenia INT AUTO_INCREMENT PRIMARY KEY,
   nazwa_zagrozenia VARCHAR(100) NOT NULL UNIQUE,
   opis TEXT
);

CREATE TABLE Wystepowanie (
   id_wystepowania INT AUTO_INCREMENT PRIMARY KEY,
   nazwa_miejsca VARCHAR(100) NOT NULL,
   typ_wody VARCHAR(50),
   kraj VARCHAR(50)
);


-- sekwencja

DROP SEQUENCE IF EXISTS seq_hodowli;
CREATE SEQUENCE seq_hodowli
START WITH 5
INCREMENT BY 5
MINVALUE 5;


CREATE TABLE Hodowle (
   id_hodowli INT PRIMARY KEY DEFAULT NEXT VALUE FOR seq_hodowli,
   nazwa_hodowli VARCHAR(100) NOT NULL,
   typ_hodowli VARCHAR(50),
   powierzchnia_m2 FLOAT CHECK (powierzchnia_m2 >= 0),
   kontakt_email VARCHAR(100),
   czy_aktywny BOOL DEFAULT TRUE
);

-- tabele lacznikowe

CREATE TABLE Dieta (
   id_ryby INT NOT NULL,
   id_jedzenia INT NOT NULL,
   ilosc_na_dzien_g FLOAT CHECK (ilosc_na_dzien_g >= 0),
   uwagi TEXT,
   PRIMARY KEY (id_ryby, id_jedzenia),
   FOREIGN KEY (id_ryby) REFERENCES Ryby(id_ryby) ON DELETE CASCADE ON UPDATE CASCADE,
   FOREIGN KEY (id_jedzenia) REFERENCES Jedzenie(id_jedzenia) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE Ryba_Zagrozenia (
   id_ryby INT NOT NULL,
   id_zagrozenia INT NOT NULL,
   poziom_zagrozenia VARCHAR(20) CHECK (poziom_zagrozenia IN ('niski','średni','wysoki')),
   PRIMARY KEY (id_ryby, id_zagrozenia),
   FOREIGN KEY (id_ryby) REFERENCES Ryby(id_ryby) ON DELETE CASCADE ON UPDATE CASCADE,
   FOREIGN KEY (id_zagrozenia) REFERENCES Zagrozenia(id_zagrozenia) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE Ryba_Wystepowanie (
   id_ryby INT NOT NULL,
   id_wystepowania INT NOT NULL,
   liczba_osobnikow INT CHECK (liczba_osobnikow >= 0),
   PRIMARY KEY (id_ryby, id_wystepowania),
   FOREIGN KEY (id_ryby) REFERENCES Ryby(id_ryby) ON DELETE CASCADE ON UPDATE CASCADE,
   FOREIGN KEY (id_wystepowania) REFERENCES Wystepowanie(id_wystepowania) ON DELETE CASCADE ON UPDATE CASCADE
);

CREATE TABLE Hodowla_Ryba (
   id_hodowli INT NOT NULL,
   id_ryby INT NOT NULL,
   liczba_osobnikow INT CHECK (liczba_osobnikow >= 0),
   PRIMARY KEY (id_hodowli, id_ryby),
   FOREIGN KEY (id_hodowli) REFERENCES Hodowle(id_hodowli) ON DELETE CASCADE ON UPDATE CASCADE,
   FOREIGN KEY (id_ryby) REFERENCES Ryby(id_ryby) ON DELETE RESTRICT ON UPDATE RESTRICT
);


-- idx

CREATE INDEX idx_typ_ryby ON Ryby(typ_ryby);
CREATE INDEX idx_nazwa_hodowli ON Hodowle(nazwa_hodowli);
CREATE INDEX idx_kraj ON Wystepowanie(kraj);
CREATE INDEX idx_typ_wody ON Wystepowanie(typ_wody);
CREATE INDEX idx_typ_hodowli ON Hodowle(typ_hodowli);
CREATE INDEX idx_czy_tropikalna ON Ryby(czy_tropikalna);

-- widoki

CREATE VIEW Widok_Ryby_Dieta AS
SELECT id_ryby, nazwa_ryby, typ_ryby, nazwa AS jedzenie, ilosc_na_dzien_g
FROM Ryby
NATURAL JOIN Dieta
NATURAL JOIN Jedzenie;

CREATE VIEW Widok_Hodowla_Ryby AS
SELECT id_hodowli, nazwa_hodowli, typ_hodowli, SUM(liczba_osobnikow) AS suma_ryb
FROM Hodowle
NATURAL JOIN Hodowla_Ryba
GROUP BY id_hodowli, nazwa_hodowli, typ_hodowli;


-- funkckja
-- Oblicza maksymalną dopuszczalną liczbę osobników danego gatunku w hodowli


DELIMITER $$

CREATE FUNCTION fn_maks_pojemnosc_hodowli(
   p_id_hodowli INT,
   p_id_ryby INT
)
RETURNS INT
DETERMINISTIC
READS SQL DATA
BEGIN
   DECLARE v_powierzchnia FLOAT;
   DECLARE v_typ VARCHAR(50);
   DECLARE v_tropikalna BOOL;
   DECLARE v_limit FLOAT;

   SELECT powierzchnia_m2
   INTO v_powierzchnia
   FROM Hodowle
   WHERE id_hodowli = p_id_hodowli;

   SELECT typ_ryby, czy_tropikalna
   INTO v_typ, v_tropikalna
   FROM Ryby
   WHERE id_ryby = p_id_ryby;

   IF v_typ = 'morska' THEN
      SET v_limit = v_powierzchnia * 2;
   ELSE
      SET v_limit = v_powierzchnia * 1.5;
   END IF;

   IF v_tropikalna = TRUE THEN
      SET v_limit = v_limit * 0.8;
   END IF;

   RETURN FLOOR(v_limit);
END$$

DELIMITER ;


-- trigery

-- zabezpieczenie przed przepełnieniem hodowli
DELIMITER $$

CREATE TRIGGER trg_sprawdz_pojemnosc
BEFORE INSERT ON Hodowla_Ryba
FOR EACH ROW
BEGIN
   DECLARE v_limit INT;

   SET v_limit = fn_maks_pojemnosc_hodowli(NEW.id_hodowli, NEW.id_ryby);

   IF NEW.liczba_osobnikow > v_limit THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Przekroczono maksymalna pojemnosc hodowli dla tego gatunku!';
   END IF;
END$$

DELIMITER ;

-- przy update
DELIMITER $$

CREATE TRIGGER trg_update_pojemnosc
BEFORE UPDATE ON Hodowla_Ryba
FOR EACH ROW
BEGIN
   DECLARE v_limit INT;

   SET v_limit = fn_maks_pojemnosc_hodowli(NEW.id_hodowli, NEW.id_ryby);

   IF NEW.liczba_osobnikow > v_limit THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Aktualizacja przekracza dopuszczalny limit hodowli!';
   END IF;
END$$

DELIMITER ;

-- blokada usunięcia ryb
DELIMITER $$

CREATE TRIGGER trg_blokuj_usuniecie_ryby
BEFORE DELETE ON Ryby
FOR EACH ROW
BEGIN
    DECLARE v_count INT;

    SELECT COUNT(*)
    INTO v_count
    FROM Hodowla_Ryba
    WHERE id_ryby = OLD.id_ryby;

    IF v_count > 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Nie mozna usunac ryby, ktora wystepuje w hodowli!';
    END IF;
END$$

DELIMITER ;

-- mail w hodowli sie robi

DELIMITER $$

CREATE TRIGGER trg_generuj_email_hodowli_insert
BEFORE INSERT ON Hodowle
FOR EACH ROW
BEGIN
   SET NEW.kontakt_email = CONCAT(LOWER(REPLACE(NEW.nazwa_hodowli, ' ', '')),'@gmail.com');
END$$

DELIMITER ;

DELIMITER $$

CREATE TRIGGER trg_generuj_email_hodowli_update
BEFORE UPDATE ON Hodowle
FOR EACH ROW
BEGIN
   IF NEW.nazwa_hodowli <> OLD.nazwa_hodowli THEN
      SET NEW.kontakt_email = CONCAT(LOWER(REPLACE(NEW.nazwa_hodowli, ' ', '')),'@gmail.com');
   END IF;
END$$

DELIMITER ;

ALTER TABLE Wystepowanie
ADD COLUMN kod_kraju CHAR(2) AFTER kraj;

ALTER TABLE Hodowle
ADD COLUMN data_zalozenia DATE DEFAULT CURRENT_DATE AFTER nazwa_hodowli;

ALTER TABLE Hodowle
ADD CONSTRAINT chk_email_format
CHECK (kontakt_email LIKE '%@%.%');

-- wiecej triggerow

DELIMITER $$

CREATE TRIGGER trg_sprawdz_typ_ryby
BEFORE INSERT ON Ryby
FOR EACH ROW
BEGIN
   IF NEW.typ_ryby NOT IN ('morska', 'slodkowodna') THEN
      SIGNAL SQLSTATE '45000'
      SET MESSAGE_TEXT = 'Nieprawidlowy typ ryby!';
   END IF;
END$$

DELIMITER ;

DELIMITER $$
CREATE TRIGGER trg_blokuj_dezaktywacje
BEFORE UPDATE ON Hodowle
FOR EACH ROW
BEGIN
   DECLARE v_count INT;

   IF NEW.czy_aktywny = FALSE AND OLD.czy_aktywny = TRUE THEN
      SELECT COUNT(*)
      INTO v_count
      FROM Hodowla_Ryba
      WHERE id_hodowli = OLD.id_hodowli;

      IF v_count > 0 THEN
         SIGNAL SQLSTATE '45000'
         SET MESSAGE_TEXT = 'Nie mozna dezaktywowac hodowli, ktora zawiera ryby!';
      END IF;
   END IF;
END$$
DELIMITER ;



