-- 1. Podsumowanie liczby osobników w hodowlach powyżej 3000 sztuk
SELECT h.nazwa_hodowli, SUM(hr.liczba_osobnikow) AS laczna_liczba_ryb
FROM Hodowle h
NATURAL JOIN Hodowla_Ryba hr
GROUP BY h.id_hodowli, h.nazwa_hodowli
HAVING SUM(hr.liczba_osobnikow) > 3000
ORDER BY laczna_liczba_ryb DESC;


-- 2. Ryby posiadające co najmniej jedno wysokie zagrożenie
SELECT r.nazwa_ryby, r.typ_ryby
FROM Ryby r
WHERE EXISTS (
   SELECT 1
   FROM Ryba_Zagrozenia rz
   WHERE rz.id_ryby = r.id_ryby AND rz.poziom_zagrozenia = 'wysoki'
);


-- 3. 5 największych ryb pod względem wagi
SELECT nazwa_ryby, waga_srednia_g
FROM Ryby
ORDER BY waga_srednia_g DESC
LIMIT 5;


-- 4. Średnia ilość jedzenia na dzień dla każdego typu ryby
SELECT r.typ_ryby, AVG(di.ilosc_na_dzien_g) AS srednia_ilosc
FROM Ryby r
NATURAL JOIN Dieta di
GROUP BY r.typ_ryby;


-- 5. Suma ryb w hodowlach dla każdej ryby
SELECT r.nazwa_ryby,
   (SELECT SUM(hr.liczba_osobnikow)
   FROM Hodowla_Ryba hr
   WHERE hr.id_ryby = r.id_ryby) AS laczna_liczba_w_hodowlach
FROM Ryby r
ORDER BY laczna_liczba_w_hodowlach DESC;


-- 6. Ryby występujące w więcej niż 6 lokalizacjach
WITH Ryby_Multilokalizacja AS (
   SELECT id_ryby, nazwa_ryby, COUNT(*) AS liczba_miejsc
   FROM Ryba_Wystepowanie
   NATURAL JOIN Ryby
   GROUP BY id_ryby, nazwa_ryby
   HAVING COUNT(*) > 6
)
SELECT nazwa_ryby, liczba_miejsc
FROM Ryby_Multilokalizacja
ORDER BY liczba_miejsc DESC;


-- 7. Średnia waga ryb według typu 
SELECT a.typ_ryby, AVG(a.waga_srednia_g) AS srednia_waga
FROM (
   SELECT typ_ryby, waga_srednia_g
   FROM Ryby
   WHERE waga_srednia_g IS NOT NULL
) a
GROUP BY a.typ_ryby
ORDER BY srednia_waga DESC;


-- 8. opis zagrożeń dla każdej ryby - poprawiona wersja
SELECT r.nazwa_ryby, GROUP_CONCAT(CONCAT(z.nazwa_zagrozenia, ' (', rz.poziom_zagrozenia, ')') SEPARATOR ', ') AS zagrozenia_skrot
FROM Ryby r
NATURAL JOIN Ryba_Zagrozenia rz
JOIN Zagrozenia z ON rz.id_zagrozenia = z.id_zagrozenia
GROUP BY r.id_ryby, r.nazwa_ryby
ORDER BY r.nazwa_ryby;


-- 9. Ryby dłuższe niż średnia długość wszystkich ryb
SELECT nazwa_ryby, dlugosc_srednia_cm
FROM Ryby
WHERE dlugosc_srednia_cm > (
   SELECT AVG(dlugosc_srednia_cm)
   FROM Ryby
)
ORDER BY dlugosc_srednia_cm DESC;


-- 10. Ryby bez przypisanej diety
SELECT r.nazwa_ryby
FROM Ryby r
LEFT JOIN Dieta d ON r.id_ryby = d.id_ryby
WHERE d.id_jedzenia IS NULL;


-- 11. Ranking ryb wg liczby wysokich zagrożeń
SELECT r.nazwa_ryby, COUNT(*) AS liczba_wysokich
FROM Ryby r
NATURAL JOIN Ryba_Zagrozenia rz
WHERE rz.poziom_zagrozenia = 'wysoki'
GROUP BY r.id_ryby, r.nazwa_ryby
ORDER BY liczba_wysokich DESC;


-- 12. Średnia liczba osobników wg kraju
SELECT w.kraj, AVG(rw.liczba_osobnikow) AS srednia_liczba
FROM Ryba_Wystepowanie rw
NATURAL JOIN Wystepowanie w
GROUP BY w.kraj
ORDER BY srednia_liczba DESC;


-- 13. Ryby jedzące więcej niż średnia ilość jedzenia
SELECT r.nazwa_ryby, SUM(di.ilosc_na_dzien_g) AS suma_jedzenia
FROM Ryby r
NATURAL JOIN Dieta di
GROUP BY r.id_ryby, r.nazwa_ryby
HAVING suma_jedzenia > (SELECT AVG(ilosc_na_dzien_g) FROM Dieta);


-- 14. Ryby obecne w wielu krajach
SELECT r.nazwa_ryby, COUNT(DISTINCT w.kraj) AS liczba_krajow
FROM Ryby r
NATURAL JOIN Ryba_Wystepowanie rw
NATURAL JOIN Wystepowanie w
GROUP BY r.id_ryby, r.nazwa_ryby
HAVING COUNT(DISTINCT w.kraj) > 1;


-- 15. Największa wagowo ryba w każdej hodowli
SELECT h.nazwa_hodowli, r.nazwa_ryby, r.waga_srednia_g
FROM Hodowle h
JOIN Hodowla_Ryba hr ON h.id_hodowli = hr.id_hodowli
JOIN Ryby r ON hr.id_ryby = r.id_ryby
WHERE r.waga_srednia_g = (
   SELECT MAX(r2.waga_srednia_g)
   FROM Hodowla_Ryba hr2
   JOIN Ryby r2 ON hr2.id_ryby = r2.id_ryby
   WHERE hr2.id_hodowli = h.id_hodowli
);


-- 16. Liczba ryb przypisanych do każdego zagrożenia
SELECT z.nazwa_zagrozenia, COUNT(rz.id_ryby) AS liczba_ryb
FROM Zagrozenia z
LEFT JOIN Ryba_Zagrozenia rz ON z.id_zagrozenia = rz.id_zagrozenia
GROUP BY z.id_zagrozenia, z.nazwa_zagrozenia
ORDER BY liczba_ryb DESC;

-- 17. Ryby z ponadprzeciętną liczbą zagrożeń
WITH Licznik AS (
   SELECT id_ryby, COUNT(*) AS ile
   FROM Ryba_Zagrozenia
   GROUP BY id_ryby
)
SELECT r.nazwa_ryby, l.ile
FROM Licznik l
NATURAL JOIN Ryby r
WHERE l.ile > (SELECT AVG(ile) FROM Licznik);


USE Rybobaza;

-- widok publiczny dla klientow
CREATE OR REPLACE VIEW Widok_Publiczny_Ryby AS
SELECT nazwa_ryby, typ_ryby, dlugosc_srednia_cm
FROM Ryby;


